_DURATION_RE = re.compile(r"\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*\Z")
_UNITS = ("d", "h", "m", "s")
_MULTIPLIERS = {"d": 86400, "h": 3600, "m": 60, "s": 1}


def parse_duration(s):
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _DURATION_RE.fullmatch(s)
    if match is None:
        raise ValueError(f"invalid duration: {s!r}")

    amounts = match.groups()
    if all(amount is None for amount in amounts):
        raise ValueError(f"invalid duration: {s!r}")

    total = 0
    for amount, unit in zip(amounts, _UNITS):
        if amount is not None:
            total += int(amount) * _MULTIPLIERS[unit]
    return total
